/**
 * T002 extractor unit tests — rules the 16 S0 fixtures do not cover.
 *
 * Each test builds a tiny synthetic repo in a temp dir (under TMPDIR,
 * i.e. ~/workspace/p024-repomapverify/.tmp) and runs the production
 * extractor on it. Nothing here touches the fixture goldens.
 */
import { existsSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, test } from "vitest";
import { extractPythonRepo } from "../../../../src/extractors/python/index.js";

const HERE = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(HERE, "..", "..", "..", "..", "..");
const TMP_BASE = process.env["TMPDIR"] ?? join(REPO_ROOT, ".tmp");

function makeRepo(files: Record<string, string>): string {
  const dir = mkdtempSync(join(TMP_BASE, "py-unit-"));
  for (const [rel, content] of Object.entries(files)) {
    const p = join(dir, rel);
    mkdirSync(dirname(p), { recursive: true });
    writeFileSync(p, content);
  }
  return dir;
}

function cleanup(dir: string): void {
  rmSync(dir, { recursive: true, force: true });
}

describe("T002 extractor edge rules", () => {
  test("parse error => PARSE_ERROR, no edges from that file", async () => {
    const dir = makeRepo({
      "main.py": "import pkg.mod\n",
      "pkg/__init__.py": "",
      "pkg/mod.py": "def broken(:\n  import os\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      const mod = r.modules.find((m) => m.relativePath === "pkg/mod.py");
      expect(mod?.parseStatus).toBe("PARSE_ERROR");
      expect(r.edges.filter((e) => e.from === "pkg/mod.py")).toEqual([]);
      expect(r.edges).toHaveLength(1); // main -> pkg/mod still extracted
    } finally {
      cleanup(dir);
    }
  });

  test("generated module: listed, but its edges leave the core set", async () => {
    const dir = makeRepo({
      "main.py": "from gen import pb\n",
      "gen/__init__.py": "# Code generated by protoc. DO NOT EDIT.\nfrom gen import real\n",
      "gen/real.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      const gen = r.modules.find((m) => m.relativePath === "gen/__init__.py");
      expect(gen?.isGenerated).toBe(true);
      expect(r.edges).toEqual([]);
      expect(r.generatedExcludedEdges.map((e) => `${e.from}->${e.to}`).sort()).toEqual([
        "gen/__init__.py->gen/real.py",
        "main.py->gen/__init__.py",
      ]);
    } finally {
      cleanup(dir);
    }
  });

  test("relative import escaping the package tree => UNKNOWN, no edge", async () => {
    const dir = makeRepo({
      "main.py": "from ... import nope\n",
      "pkg/__init__.py": "",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges).toEqual([]);
      expect(r.unknownImports).toHaveLength(1);
      expect(r.unknownImports[0]?.reason).toBe("RELATIVE_ESCAPE");
      expect(r.unknownImports[0]?.specifier).toBe("...");
    } finally {
      cleanup(dir);
    }
  });

  test("wildcard import => edge to the base module only", async () => {
    const dir = makeRepo({
      "main.py": "from pkg import *\n",
      "pkg/__init__.py": "",
      "pkg/sub.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges.map((e) => `${e.from}->${e.to}`)).toEqual([
        "main.py->pkg/__init__.py",
      ]);
    } finally {
      cleanup(dir);
    }
  });

  test("__import__ literal resolves; variable => DYNAMIC_IMPORT_UNKNOWN", async () => {
    const dir = makeRepo({
      "main.py": 'x = __import__("pkg.mod")\ny = __import__(name)\n',
      "pkg/__init__.py": "",
      "pkg/mod.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges.map((e) => `${e.from}->${e.to}`)).toEqual([
        "main.py->pkg/mod.py",
      ]);
      expect(r.dynamicUnknown.map((d) => d.kind)).toEqual([
        "DUNDER_IMPORT_VARIABLE",
      ]);
    } finally {
      cleanup(dir);
    }
  });

  test("importlib literal resolves; exec(import-string) => dynamic; exec('x=1') ignored", async () => {
    const dir = makeRepo({
      "main.py":
        'import importlib\nm = importlib.import_module("pkg.mod")\nexec("import os")\nexec("x = 1")\n',
      "pkg/__init__.py": "",
      "pkg/mod.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges.map((e) => `${e.from}->${e.to}`)).toEqual([
        "main.py->pkg/mod.py",
      ]);
      expect(r.dynamicUnknown.map((d) => d.kind)).toEqual([
        "EXEC_EVAL_IMPORT",
      ]);
    } finally {
      cleanup(dir);
    }
  });

  test("unresolvable repo-local import => UNKNOWN, never an edge or external", async () => {
    const dir = makeRepo({
      "main.py": "import billing.refunds\n",
      "billing/__init__.py": "",
      "billing/api.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges).toEqual([]);
      expect(r.externalImports).toEqual([]);
      expect(r.unknownImports).toHaveLength(1);
      expect(r.unknownImports[0]).toMatchObject({
        specifier: "billing.refunds",
        reason: "UNRESOLVABLE_REPO_LOCAL",
      });
    } finally {
      cleanup(dir);
    }
  });

  test("duplicate imports collapse to one edge per (from, to) pair", async () => {
    const dir = makeRepo({
      "main.py": "import pkg.mod\nimport pkg.mod\nfrom pkg import mod\n",
      "pkg/__init__.py": "",
      "pkg/mod.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      // `from pkg import mod` also edges to the base package __init__.py,
      // so there are 2 distinct edges — but main->pkg/mod.py occurs once
      // despite being stated three times.
      expect(r.edges.map((e) => `${e.from}->${e.to}`).sort()).toEqual([
        "main.py->pkg/__init__.py",
        "main.py->pkg/mod.py",
      ]);
      const modEdge = r.edges.find((e) => e.to === "pkg/mod.py");
      expect(modEdge?.conditional).toBe(false);
      expect(modEdge?.evidence.line).toBe(1); // earliest statement wins
    } finally {
      cleanup(dir);
    }
  });

  test("src/root shadowing: repo-root file wins the dotted name", async () => {
    const dir = makeRepo({
      "main.py": "import app\nimport app.util\n",
      "app.py": "ROOT = 1\n",
      "src/app/__init__.py": "",
      "src/app/util.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges.map((e) => `${e.from}->${e.to}`).sort()).toEqual([
        "main.py->app.py",
        "main.py->src/app/util.py",
      ]);
    } finally {
      cleanup(dir);
    }
  });

  test("namespace package without __init__.py does not resolve (frozen scope)", async () => {
    const dir = makeRepo({
      "main.py": "import ns.mod\n",
      "ns/mod.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges).toEqual([]);
      expect(r.unknownImports[0]?.reason).toBe("UNRESOLVABLE_REPO_LOCAL");
    } finally {
      cleanup(dir);
    }
  });

  test("import inside a function body is still extracted", async () => {
    const dir = makeRepo({
      "main.py": "def f():\n    import pkg.mod\n    return pkg.mod\n",
      "pkg/__init__.py": "",
      "pkg/mod.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges.map((e) => `${e.from}->${e.to}`)).toEqual([
        "main.py->pkg/mod.py",
      ]);
      expect(r.edges[0]?.evidence.line).toBe(2);
    } finally {
      cleanup(dir);
    }
  });

  test("no .repomapverify.toml => no entrypoints, everything isolated", async () => {
    const dir = makeRepo({
      "main.py": "import pkg.mod\n",
      "pkg/__init__.py": "",
      "pkg/mod.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.entrypoints).toEqual([]);
      expect(r.reachableFromEntrypoints).toEqual([]);
      expect(r.isolatedModules).toEqual([
        "main.py",
        "pkg/__init__.py",
        "pkg/mod.py",
      ]);
    } finally {
      cleanup(dir);
    }
  });

  test("file over the 1 MiB cap => TOO_LARGE, no edges", async () => {
    const dir = makeRepo({
      "main.py": "import pkg.mod\n",
      "pkg/__init__.py": "",
      "pkg/mod.py": "# " + "x".repeat(1024 * 1024 + 10) + "\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      const mod = r.modules.find((m) => m.relativePath === "pkg/mod.py");
      expect(mod?.parseStatus).toBe("TOO_LARGE");
      expect(r.edges.filter((e) => e.from === "pkg/mod.py")).toEqual([]);
    } finally {
      cleanup(dir);
    }
  });

  test("from-import of an attribute of a plain module => no sub-edge", async () => {
    const dir = makeRepo({
      "main.py": "from pkg.mod import helper\n",
      "pkg/__init__.py": "",
      "pkg/mod.py": "def helper():\n    pass\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges.map((e) => `${e.from}->${e.to}`)).toEqual([
        "main.py->pkg/mod.py",
      ]);
    } finally {
      cleanup(dir);
    }
  });

  test("self-import via `from . import x` inside __init__ skips the self edge", async () => {
    const dir = makeRepo({
      "main.py": "from pkg import sub\n",
      "pkg/__init__.py": "from . import sub\n",
      "pkg/sub.py": "X = 1\n",
    });
    try {
      const r = await extractPythonRepo(dir);
      expect(r.edges.map((e) => `${e.from}->${e.to}`).sort()).toEqual([
        "main.py->pkg/__init__.py",
        "main.py->pkg/sub.py",
        "pkg/__init__.py->pkg/sub.py",
      ]);
    } finally {
      cleanup(dir);
    }
  });
});
